<?php
namespace App\Repositories;
use App\Models\Job; use App\Repositories\Contracts\JobRepositoryInterface; use Illuminate\Contracts\Pagination\LengthAwarePaginator;
class EloquentJobRepository implements JobRepositoryInterface { public function paginatePublished(array $filters=[],int $perPage=12):LengthAwarePaginator{return Job::query()->with(['company.user','category'])->withCount('applications')->where('status','published')->when($filters['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','like',"%{$v}%")->orWhere('location','like',"%{$v}%")))->when($filters['category']??null,fn($q,$v)=>$q->where('job_category_id',$v))->when($filters['location']??null,fn($q,$v)=>$q->where('location','like',"%{$v}%"))->latest()->paginate($perPage)->withQueryString();} public function create(array $data):Job{return Job::create($data);} public function update(Job $job,array $data):Job{$job->update($data);return $job->refresh();} public function delete(Job $job):void{$job->delete();} }
